-- Nov 5 Hot Lab follow-through, wrapped for Monday (Sean, 2026-11-05 to 07). Applied through
-- execute_sql; safe to run twice. Start-here row: monday-pickup-nov-9.

-- step: Audit Hub renamed (Sean, Nov 5: the audit is a component in each hub)
update public.bcps_assignment_tags set title_override = 'Audit in every hub: District Web Team view first', description_override = 'Sean (Nov 5): the audit is a component inside each hub, not a hub of its own, and not a widget (widgets are public embeds). The shared audit component (SiteAudit) already runs in the WCM home, director home, department page and school pages, each with its role''s view. Missing: the District Web Team view. Build it as an Audit section in the District Web Team hub: every department''s audit progress at a glance, the still-stuck queue (bcps_audit_questions, today only at /audit-questions with no navigation link), the rule review (/audit-rules-review) and the Finalsite items. Then keep improving the WCM and director views in place (clearer messages, the schedule button once the audit is complete).', updated_at = now() where assignment_slug = 'audit-hub';
insert into public.bcps_assignment_notes (assignment_slug, note_text, author) select 'audit-hub', 'Nov 5 (Sean): renamed from Audit Hub. The audit is a component in each hub, with a view per role; the District Web Team view is built first.', 'Logan' where not exists (select 1 from public.bcps_assignment_notes where assignment_slug='audit-hub' and note_text like 'Nov 5 (Sean): renamed from Audit Hub.%');

-- step: certification email status
update public.bcps_assignment_tags set title_override='Certification wrap-up email to all WCMs (not sent yet)', deadline_date='2026-11-09', updated_at=now(), description_override='Approved by Sean Nov 5: thanks, a LAB note (disregard LAB notifications if certified; we close completion out in LAB; questions by reply), the access pause for anyone not certified, the audit focus with a button to the Department WCM Guide, and the Nov 10 Hot Lab. Built as campaign cert-update-2026-11-06 on the Certification page (Outreach tab), live on production (PR 248); it sends one message to all 77 roster WCMs. NOT SENT as of Sat Nov 7. Before sending Monday, two lines need new dates: "closed yesterday, Thursday, November 5" and "Starting Monday, November 9, access ... is paused" (Sean to decide the new pause date). The page sends on click only; there is no scheduled send yet.' where assignment_slug='cert-congrats-message';

-- step: new assignments
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at)
select 'outreach-campaign-menu-schedule','in-progress','high','Certification Outreach: pending campaigns menu and scheduled sends','Sean (Nov 6): (1) a campaign that is set up but not sent should be pickable in the Campaign dropdown, loading the list so Send is ready; (2) a Schedule option to send at a set date and time. (1) is built and pushed, not merged: commit 0a66502 on branch claude/sharp-shannon-4skohw (Campaign field becomes a menu: Ready to send, Already sent, New campaign; pending rows marked in the Campaigns table; a stale list response can no longer leave the wrong people checked). Waiting on Sean to say merge. (2) is not built: plan is a send-at time stored with the campaign, sent by the same 8 AM pg_cron job that runs recurring emails (checking every few minutes), with scheduled sends listed and cancellable.','Logan','2026-11-09'::date,'https://bcpsmarcomm.com/playbooks/bcps-wcm-cert-followup-2026-11-03',now(),now()
where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='outreach-campaign-menu-schedule');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at)
select 'monday-pickup-nov-9','in-progress','high','Monday pickup: Nov 5 Hot Lab follow-through (start here)','Start here Monday, Nov 9. In the chat, say: "pick up the Nov 5 Hot Lab follow-through from Web Team Assignments." In order: (1) Certification wrap-up email: fix the two dates, then send (cert-congrats-message). (2) Say merge for the pending Campaign menu (outreach-campaign-menu-schedule), then decide on the Schedule option. (3) Open Run Audit on your dashboard and check the new Audit team tools (audit-hub, still-stuck-queue-visibility): 9 still-stuck questions are waiting. (4) Click your Nov 5 Hot Lab calls into the Audit Rule Review: 0 of 36 rules have a decision (audit-followups-nov-3). (5) Heading size mock-ups for the Tuesday, Nov 10 Hot Lab (heading-sizes). (6) Add the Nov 5 recording link to the Hot Lab note (department-hot-labs). Everything else from Nov 5 is in its own assignment under its playbook. Repo handoff: docs/handoff/2026-11-07-hot-lab-1105-followthrough.md.','Sean A. Russell','2026-11-09'::date,'https://bcpsmarcomm.com/playbooks/bcps-feedback',now(),now()
where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='monday-pickup-nov-9');

