insert into public.bcps_assignment_notes (assignment_slug, note_text, author)
select v.slug, v.note, 'Logan' from (values
('cert-congrats-message','Nov 7: not sent. Campaign cert-update-2026-11-06 is live on the Certification page (Outreach tab), 77 people checked. Update the two date lines before Monday''s send.'),
('outreach-campaign-menu-schedule','Nov 7: campaign menu built and pushed (0a66502), waiting on merge. Scheduled send not built yet.'),
('audit-hub','Nov 5: Audit team tools live on the Run Audit tab for SuperAdmin and the District Web Team (PR 252): still-stuck questions (9 open), rule review (0 of 36 decided), Finalsite items (18 rules). Not yet seen signed in. Next: Sean checks it; then the WCM and director views.'),
('still-stuck-queue-visibility','Nov 5: fixed in PR 252. The queue is linked from the Run Audit tab, and the District Web Team (audit-rules-review grant) can now read and answer questions; before, only admin roles could. Close once Sean or a District Web Team member answers one signed in.'),
('audit-followups-nov-3','Nov 7: the Audit Rule Review still shows 0 decisions. Sean''s Nov 5 Hot Lab calls to click in: text-heavy images keep as is; linked PDFs change once the PDF tool exists; headings need input on sizes; overview page keep.'),
('department-hot-labs','Nov 5 Hot Lab notes filed: https://bcpsmarcomm.com/playbooks/wcm-hot-labs/bcps-hot-lab-dept-wcms-2026-11-05. The recording link is still missing (not in SharePoint search on Nov 5); add it to the note when Teams posts it.'),
('certification-page','Nov 7: the Certification page now has Overview (Where everyone is, Leaderboard), Outreach and Roster tabs with status sub-tabs, built on main between Nov 5 and 6. Check it against the Nov 5 request and close or list what is left.')
) as v(slug, note)
where not exists (select 1 from public.bcps_assignment_notes n where n.assignment_slug=v.slug and n.note_text=v.note);

